      seen[tok] = true;
      unique.push(tok);
      frequencies[tok] = 0;
    }
    frequencies[tok] = frequencies[tok] + 1;
  }
  return {
    text: tokens.join(' '),
    tokens: tokens,
    count: tokens.length,
    unique: unique,
    frequencies: frequencies
  };
}"
